#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v, w;
    bool operator<(const Edge& other) const {
        return w > other.w;
    }
};

struct DSU {
    vector<int> parent, size;

    DSU(int n) : parent(n + 1), size(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, B;
    cin >> N >> B;

    vector<Edge> edges(B);
    for (auto& e : edges) cin >> e.u >> e.v >> e.w;
    sort(edges.begin(), edges.end());

    vector<vector<pair<int, int>>> tree(N + 1);
    DSU dsu(N);
    for (const auto& e : edges) {
        if (dsu.unite(e.u, e.v)) {
            tree[e.u].push_back({e.v, e.w});
            tree[e.v].push_back({e.u, e.w});
        }
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    const int INF = INT_MAX;
    vector<vector<int>> up(LOG, vector<int>(N + 1));
    vector<vector<int>> mn(LOG, vector<int>(N + 1, INF));
    vector<int> depth(N + 1, -1);

    queue<int> q;
    depth[1] = 0;
    up[0][1] = 1;
    q.push(1);

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        for (auto [to, weight] : tree[v]) {
            if (depth[to] != -1) continue;
            depth[to] = depth[v] + 1;
            up[0][to] = v;
            mn[0][to] = weight;
            q.push(to);
        }
    }

    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= N; ++v) {
            up[k][v] = up[k - 1][up[k - 1][v]];
            mn[k][v] = min(mn[k - 1][v], mn[k - 1][up[k - 1][v]]);
        }
    }

    int C;
    cin >> C;
    while (C--) {
        int x, y;
        cin >> x >> y;

        int answer = INF;
        if (depth[x] < depth[y]) swap(x, y);

        int difference = depth[x] - depth[y];
        for (int k = LOG - 1; k >= 0; --k) {
            if (difference & (1 << k)) {
                answer = min(answer, mn[k][x]);
                x = up[k][x];
            }
        }

        if (x != y) {
            for (int k = LOG - 1; k >= 0; --k) {
                if (up[k][x] != up[k][y]) {
                    answer = min(answer, mn[k][x]);
                    answer = min(answer, mn[k][y]);
                    x = up[k][x];
                    y = up[k][y];
                }
            }
            answer = min(answer, mn[0][x]);
            answer = min(answer, mn[0][y]);
        }

        cout << answer << '\n';
    }

    return 0;
}
